/**
 * @sw-package framework
 *
 * The Jest environment needs test/_mocks_/entity-schema.json. Locally it is generated by
 * bin/build-administration.sh (bin/console framework:schema), which needs a running installation.
 * In CI there is none, so a committed snapshot (test/_fixtures_/entity-schema.json) is used instead.
 *
 * Usage:
 *   node scripts/entity-schema-fixture/index.mjs ensure  -> copy the snapshot to test/_mocks_/ if no schema exists there
 *   node scripts/entity-schema-fixture/index.mjs update  -> store the current test/_mocks_/ schema as the new snapshot
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const adminRoot = path.join(path.dirname(fileURLToPath(import.meta.url)), '../..');
const generatedSchema = path.join(adminRoot, 'test/_mocks_/entity-schema.json');
const fixtureSchema = path.join(adminRoot, 'test/_fixtures_/entity-schema.json');

// Entities of locally installed plugins are not part of muckiware/master and must not end up in the snapshot.
const PLUGIN_ENTITY_PREFIXES = ['muwa_'];

function copy(from, to) {
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(from, to);
    console.info(`Copied ${path.relative(adminRoot, from)} -> ${path.relative(adminRoot, to)}`);
}

function ensure() {
    if (fs.existsSync(generatedSchema)) {
        console.info('Generated entity schema found, keeping it.');
        return;
    }

    if (!fs.existsSync(fixtureSchema)) {
        throw new Error(`Entity schema snapshot missing: ${fixtureSchema}`);
    }

    copy(fixtureSchema, generatedSchema);
}

function update() {
    if (!fs.existsSync(generatedSchema)) {
        throw new Error('No generated entity schema found. Run bin/build-administration.sh in the project first.');
    }

    const schema = JSON.parse(fs.readFileSync(generatedSchema, 'utf-8'));
    const filtered = Object.fromEntries(
        Object.entries(schema).filter(([entity]) => !PLUGIN_ENTITY_PREFIXES.some((prefix) => entity.startsWith(prefix))),
    );

    fs.mkdirSync(path.dirname(fixtureSchema), { recursive: true });
    fs.writeFileSync(fixtureSchema, `${JSON.stringify(filtered)}\n`);
    console.info(
        `Stored ${Object.keys(filtered).length} entities in ${path.relative(adminRoot, fixtureSchema)} ` +
        `(${Object.keys(schema).length - Object.keys(filtered).length} plugin entities skipped)`,
    );
}

const commands = { ensure, update };
const command = commands[process.argv[2]];

if (!command) {
    console.error('Usage: node scripts/entity-schema-fixture/index.mjs <ensure|update>');
    process.exit(1);
}

command();
